'use strict';
const numberFormat=n=>n.toLocaleString('en-US');
const ipNumber=octets=>octets.reduce((value,octet)=>value*256+octet,0);
const numberIP=n=>[24,16,8,0].map(shift=>Math.floor(n/2**shift)%256).join('.');
const binaryIP=n=>numberIP(n).split('.').map(v=>(+v).toString(2).padStart(8,'0'));
function dissectCIDR(input){
 const match=String(input).trim().match(/^([^/\s]+)\s*\/\s*(\d{1,2})$/);
 if(!match)throw Error('Enter four decimal octets or four 8-bit binary groups, followed by /0 through /32.');
 const prefix=Number(match[2]),parts=match[1].split('.');if(prefix>32||parts.length!==4)throw Error('IPv4 needs four octets and a prefix from 0 through 32.');
 const binary=parts.every(p=>/^[01]{8}$/.test(p));
 if(!binary&&parts.some(p=>!/^\d{1,3}$/.test(p)||Number(p)>255))throw Error('Each decimal octet must be a whole number from 0 through 255.');
 const octets=parts.map(p=>parseInt(p,binary?2:10)),value=ipNumber(octets),host=32-prefix,total=2**host,network=Math.floor(value/total)*total,last=network+total-1,mask=2**32-total;
 return {input:String(input),octets,value,prefix,host,total,network,last,mask,usable:prefix<=30?total-2:prefix===31?2:1,bits:binaryIP(value).join(''),networkBits:binaryIP(network).join(''),lastBits:binaryIP(last).join('')};
}
let lastSubnet='';
function randomSubnet(){let text;do{const prefix=8+Math.floor(Math.random()*23),value=ipNumber([10,Math.floor(Math.random()*256),Math.floor(Math.random()*256),Math.floor(Math.random()*256)]),total=2**(32-prefix);text=numberIP(Math.floor(value/total)*total)+'/'+prefix}while(text===lastSubnet);lastSubnet=text;return text}
let decoderState={input:'73.5.0.0/17',step:0,selected:16};
function decoderHome(){view='decoder';renderModeBar();$('#app').innerHTML='<div id="decoder-root"></div>';mountDecoder($('#decoder-root'),decoderState)}
function openDecoder(input){let state={input:input||'73.5.0.0/17',step:0,selected:16};const panel=document.createElement('dialog');panel.className='lesson-dialog decoder-dialog';panel.innerHTML='<button class="close-lesson">Return to question</button><div class="decoder-root"></div>';document.body.append(panel);panel.querySelector('button').onclick=()=>panel.close();panel.onclose=()=>panel.remove();mountDecoder(panel.querySelector('.decoder-root'),state,true);panel.showModal()}
function bitGrid(d,bits,selected,interactive=true){return `<div class="bit-grid">${[0,1,2,3].map(o=>`<div class="octet-group"><span>Octet ${o+1} · ${parseInt(bits.slice(o*8,o*8+8),2)}</span><div class="eight-bits">${Array.from({length:8},(_,j)=>{const i=o*8+j,network=i<d.prefix;return interactive?`<button class="bit ${network?'network-bit':'host-bit'} ${i===selected?'selected-bit':''}" data-bit="${i}" aria-pressed="${i===selected}" aria-label="Bit ${i+1}, octet ${o+1}, ${network?'network':'host'} bit, value ${bits[i]}">${bits[i]}</button>`:`<span class="bit ${network?'network-bit':'host-bit'}">${bits[i]}</span>`}).join('')}</div><small>${Array.from({length:8},(_,j)=>o*8+j<d.prefix?'N':'H').join(' ')}</small></div>`).join('')}</div>`}
function subnetQuestions(d){const id='subnet-'+numberIP(d.network)+'-'+d.prefix;const create=(kind,q,answer,wrong,remember)=>({id:id+'-'+kind,ch:4,kind:'number',q,display:`${numberIP(d.network)}<mark>/${d.prefix}</mark>`,answer:String(answer),options:[String(answer),...wrong.map(String)].filter((v,i,a)=>a.indexOf(v)===i).slice(0,4),remember:'Remember: '+remember,explain:remember,lessonId:'notes-4-2',decoderInput:numberIP(d.network)+'/'+d.prefix,note:'Generated subnet practice'});const numeric=(n,alternatives)=>{const unique=[...new Set(alternatives)].filter(v=>v!==n&&v>=0);for(let i=1;unique.length<3;i++)if(!unique.includes(n+i))unique.push(n+i);return unique.slice(0,3)};
 return [
 create('hosts','How many host bits remain?',d.host,numeric(d.host,[d.prefix,32,d.host+1,d.host-1]),`IPv4 has 32 bits. The /${d.prefix} prefix uses ${d.prefix} network bits, leaving 32 − ${d.prefix} = ${d.host} host bits.`),
 create('total','How many total addresses are in this block?',numberFormat(d.total),numeric(d.total,[d.total*2,Math.max(1,d.total/2),Math.max(0,d.total-2)]).map(numberFormat),`Each host bit can be 0 or 1. ${d.host} host bits give 2^${d.host} = ${numberFormat(d.total)} combinations, so the block contains ${numberFormat(d.total)} addresses.`),
 create('usable','How many usable host addresses can be assigned in this example?',numberFormat(d.usable),numeric(d.usable,[d.total,d.total+2,Math.max(0,d.total-1)]).map(numberFormat),d.prefix<=30?`Start with ${numberFormat(d.total)} addresses. Reserve the all-zero host value for the network address and the all-one host value for broadcast: ${numberFormat(d.total)} − 2 = ${numberFormat(d.usable)}.`:d.prefix===31?'This /31 is treated as a point-to-point link. Both addresses can identify endpoints; there is no directed broadcast address.':'A /32 identifies one address. It is a host route, not a traditional subnet with a separate broadcast address.'),
 create('last',d.prefix<=30?'What is the subnet’s broadcast address?':'What is the last address in this block?',numberIP(d.last),numeric(d.last,[d.network,(d.last+1)%2**32,(d.last+256)%2**32,(d.last+2)%2**32]).map(numberIP),`Keep the ${d.prefix} network bits. Set the ${d.host} host bits to 1. The octets become ${binaryIP(d.last).map(b=>b+' = '+parseInt(b,2)).join('; ')}. That gives ${numberIP(d.last)}.${d.prefix>=31?' This special prefix has no separate directed broadcast address.':''}`)
 ];
}
function mountDecoder(root,state,inDialog=false){
 root.innerHTML=`<div class="decoder"><span class="tag">Chapter 4 · IPv4 addressing & subnetting</span><h1>Dissect an address</h1><p>A subnet is a group of addresses. We’ll find the shared part, count the changing bits, and build the last address one step at a time.</p>${jargonChips(['Bit','Octet','Binary','Subnet','Prefix','Host','Network address','Broadcast address'])}<form class="cidr-form"><label>IPv4 address / prefix<input name="cidr" value="${esc(state.input)}" aria-describedby="cidr-help" required></label><button class="primary">Show this address</button></form><p id="cidr-help" class="tiny muted">Decimal: 192.168.12.34/24 · Binary: 01001001.00000101.00000000.00000000/17</p><div class="actions"><button data-example="73.5.0.0/17">Guide example /17</button><button data-example="192.168.12.34/24">Host example /24</button><button class="random-subnet">Generate another subnet</button></div><label class="prefix-control">Network prefix: <output class="prefix-output"></output><input type="range" class="prefix-slider" min="0" max="32" aria-label="Network prefix length"></label><p class="cidr-error" role="alert"></p><div class="decoder-body"></div></div>`;
 const show=()=>{let d;try{d=dissectCIDR(state.input)}catch(e){root.querySelector('.cidr-error').textContent=e.message;return}root.querySelector('.cidr-error').textContent='';root.querySelector('.prefix-slider').value=d.prefix;root.querySelector('.prefix-output').textContent='/'+d.prefix;const selected=Math.min(31,Math.max(0,state.selected)),octet=Math.floor(selected/8),within=selected%8,networkCount=Math.max(0,Math.min(8,d.prefix-octet*8));
 const steps=[
 `<h2>1. Start with the pieces</h2><p><b>${numberIP(d.value)}</b> is written as four numbers separated by dots. Each number is an <b>octet</b>: a group of eight bits. Four groups × eight bits = <b>32 bits</b>.</p><p>The slash number <b>/${d.prefix}</b> counts network bits. It does not mean ${d.prefix} addresses or ${d.prefix} octets.</p>`,
 `<h2>2. Divide network bits from host bits</h2><p>The first <b>${d.prefix} bits</b> belong to the network prefix. The remaining <b>32 − ${d.prefix} = ${d.host} bits</b> are host bits, which vary within the block.</p><ol>${[0,1,2,3].map(o=>`<li>Octet ${o+1}: ${Math.max(0,Math.min(8,d.prefix-o*8))} network bits and ${8-Math.max(0,Math.min(8,d.prefix-o*8))} host bits.</li>`).join('')}</ol><p>${d.prefix%8?`After ${Math.floor(d.prefix/8)} complete octet${Math.floor(d.prefix/8)===1?'':'s'}, the next ${d.prefix%8} bit${d.prefix%8===1?' is a network bit':'s are network bits'}. Bit ${d.prefix} is the final network bit; bit ${d.prefix+1} starts the host portion.`:`The prefix ends ${d.prefix===0?'before the first octet':'at an octet boundary'}.`}</p>`,
 `<h2>3. Count the possible addresses</h2><p>Each host bit has two choices: <b>0 or 1</b>. One bit gives 2 choices; two bits give 2 × 2 = 4; three give 2 × 2 × 2 = 8.</p><p>With ${d.host} host bits: <b>2^${d.host} = ${numberFormat(d.total)} total addresses</b>. The exponent tells you how many binary positions can vary.</p><p>${d.prefix<=30?`For a traditional IPv4 subnet, reserve 1 network address and 1 broadcast address: <b>${numberFormat(d.total)} − 1 − 1 = ${numberFormat(d.usable)} usable host addresses</b>.` : d.prefix===31?'A /31 point-to-point link uses both addresses for its two endpoints. Do not subtract two. There is no directed broadcast address.':'A /32 names one address, often as a host route. Do not subtract two; there is no separate network or broadcast reservation.'}</p>`,
 `<h2>4. Build the subnet mask</h2><p>A subnet mask marks the roles of the bits: <b>1 means network position; 0 means host position</b>. It is not the same thing as the address’s actual bit values.</p><p>${binaryIP(d.mask).map(b=>`<code>${b}</code> = ${parseInt(b,2)}`).join(' · ')}</p><p>The mask is <b>${numberIP(d.mask)}</b>. Eight 1s give 128 + 64 + 32 + 16 + 8 + 4 + 2 + 1 = 255.</p>`,
 `<h2>5. Find the network address</h2><p>Keep the blue network bits exactly as they are. Set every green host bit to <b>0</b>.</p>${bitGrid(d,d.networkBits,-1,false)}<p>The network address is <b>${numberIP(d.network)}</b>. ${d.value!==d.network?`Your input ${numberIP(d.value)} is inside this block; it is not the block’s first address.`:'Your input is already the first address of the block.'}</p>`,
 `<h2>6. Build the broadcast address</h2><p>${d.prefix<=30?'The broadcast address uses the largest host-bit combination.':'This special prefix has no separate directed broadcast. We can still calculate the last numeric address in the block.'} Keep the blue network bits. Change every green host bit to <b>1</b>.</p>${bitGrid(d,d.lastBits,-1,false)}<div class="octet-math">${binaryIP(d.last).map((b,o)=>{const values=[128,64,32,16,8,4,2,1].filter((v,j)=>b[j]==='1');return `<p><b>Octet ${o+1}:</b> ${binaryIP(d.value)[o]} → ${b}<br>${values.join(' + ')||'0'} = <b>${parseInt(b,2)}</b></p>`}).join('')}</div><p>Put the four decimal octets together: <b>${numberIP(d.last)}</b>.</p><p class="muted">The value 01111111 is 64 + 32 + 16 + 8 + 4 + 2 + 1 = 127. The leading zero means the 128 position is not included.</p>`
 ];
 root.querySelector('.decoder-body').innerHTML=`<section class="card teaching-card"><div class="bit-legend"><span class="network-label">Blue / N = network bits</span><span class="host-label">Green / H = host bits</span></div>${bitGrid(d,d.bits,selected)}<div class="bit-explanation" aria-live="polite"><b>Selected bit ${selected+1}</b>: octet ${octet+1}, position ${within+1} inside that octet. Its place value is <b>${2**(7-within)}</b>.<p>This is a <b>${selected<d.prefix?'network':'host'} bit</b> because its overall position ${selected+1} is ${selected<d.prefix?'within':'after'} the first ${d.prefix} bits. Octet ${octet+1} has ${networkCount} network bit${networkCount===1?'':'s'}. A 0 can still be a network bit—the role depends on position, not whether its value is 0 or 1.</p></div><div class="subnet-facts"><div>Total bits<b>32</b></div><div>Network bits<b>${d.prefix}</b></div><div>Host bits<b>${d.host}</b></div><div>Subnet mask<b>${numberIP(d.mask)}</b></div><div>Total addresses<b>${numberFormat(d.total)}</b></div><div>${d.prefix>=31?'Usable addresses (special case)':'Usable hosts'}<b>${numberFormat(d.usable)}</b></div></div></section><section class="card teaching-card" aria-live="polite">${steps[state.step]}</section><div class="row spread"><button class="decoder-prev" ${state.step===0?'disabled':''}>← Previous step</button><span>Step ${state.step+1} / 6</span><button class="decoder-next primary" ${state.step===5?'disabled':''}>Next step →</button></div>${!inDialog?'<div class="actions"><button class="practice-current">Practice this example</button><button class="practice-new primary">Try a new practice subnet</button></div>':''}<details class="teach-before"><summary>References and special cases</summary><p>The traditional subtract-two rule has exceptions. <a href="https://www.rfc-editor.org/rfc/rfc3021" target="_blank" rel="noreferrer">RFC 3021 explains /31 point-to-point links.</a> /32 identifies one address. The tool calculates blocks; it does not claim every mathematical block is available for public allocation.</p></details>`;
 root.querySelectorAll('[data-bit]').forEach(b=>b.onclick=()=>{state.selected=+b.dataset.bit;show()});root.querySelector('.decoder-prev').onclick=()=>{state.step--;show()};root.querySelector('.decoder-next').onclick=()=>{state.step++;show()};root.querySelector('.prefix-slider').oninput=e=>{const value=e.target.value;state.input=numberIP(d.value)+'/'+value;root.querySelector('[name=cidr]').value=state.input;show()};
 if(!inDialog){root.querySelector('.practice-current').onclick=()=>start('subnet',subnetQuestions(d));root.querySelector('.practice-new').onclick=()=>{state.input=randomSubnet();state.step=0;start('subnet',subnetQuestions(dissectCIDR(state.input)))}}
 };
 root.querySelector('form').onsubmit=e=>{e.preventDefault();const input=root.querySelector('[name=cidr]').value;try{dissectCIDR(input);state.input=input;state.step=0;show()}catch(error){root.querySelector('.cidr-error').textContent=error.message}};
 root.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{state.input=b.dataset.example;state.step=0;mountDecoder(root,state,inDialog)});root.querySelector('.random-subnet').onclick=()=>{state.input=randomSubnet();state.step=0;mountDecoder(root,state,inDialog)};show();
}
